-- Exact-project read-only catalog only. No data records, tokens or credentials.
with expected_helpers(signature) as (values
('public.operational_day_start(timestamptz)'),('public.get_setting_int(text,integer)'),('public.mz_latest_verified_check(uuid,timestamptz,timestamptz)'),('public.custodial_canonical_utc_millis(timestamptz)'),('public.sch_service_date(timestamptz)'),('public.static_weekly_v6_schedule_authority_state(date)'),('public.custodial_operational_location_assignments(date)'),('public.custodial_open_work()'),('public.place_operational_location_name(uuid,timestamptz)'),('custodial_release_identity.read_current_original_dashboard_completions_v1()')), helpers as (
 select e.signature,p.oid is not null present,r.rolname owner,p.prosecdef security_definer,
  p.provolatile volatility,p.proconfig configuration,
  case when p.oid is null then null else md5(p.prosrc) end body_md5,
  case when p.oid is null then null else md5(pg_get_functiondef(p.oid)) end definition_md5,
  case when p.oid is null then false else has_function_privilege('custodial_application_reader',p.oid,'EXECUTE') end reader_execute,
  (select jsonb_agg(jsonb_build_object('grantee',coalesce(grantee.rolname,'PUBLIC'),'privilege',acl.privilege_type,'grant_option',acl.is_grantable) order by acl.grantee)
   from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl left join pg_roles grantee on grantee.oid=acl.grantee) acl
 from expected_helpers e left join pg_proc p on p.oid=to_regprocedure(e.signature)
 left join pg_roles r on r.oid=p.proowner
), required_native_columns(relation_name,column_name) as (values
('public.custodial_offline_reconciliation_records','client_completion_id'),('public.custodial_offline_reconciliation_records','client_session_id'),('public.custodial_offline_reconciliation_records','completion_response_id'),('public.custodial_offline_reconciliation_records','context_id'),('public.custodial_offline_reconciliation_records','credential_id'),('public.custodial_offline_reconciliation_records','device_id'),('public.custodial_offline_reconciliation_records','location_id'),('public.custodial_offline_reconciliation_records','occurrence_fingerprint'),('public.custodial_offline_reconciliation_records','occurrence_id'),('public.custodial_offline_reconciliation_records','original_employee_id'),('public.custodial_offline_reconciliation_records','payload_json'),('public.custodial_offline_reconciliation_records','reconciliation_id'),('public.custodial_offline_reconciliation_records','session_id'),('public.custodial_offline_reconciliation_records','state'),('public.custodial_offline_actor_contexts','client_session_id'),('public.custodial_offline_actor_contexts','context_id'),('public.custodial_offline_actor_contexts','credential_id'),('public.custodial_offline_actor_contexts','device_id'),('public.custodial_offline_actor_contexts','employee_id'),('public.custodial_offline_actor_contexts','location_id'),('public.custodial_offline_actor_contexts','native_completed_at'),('public.custodial_offline_actor_contexts','native_completion_attestation_sha256'),('public.custodial_offline_actor_contexts','native_completion_attestation_version'),('public.custodial_offline_actor_contexts','native_finish_scan_entry_id'),('public.custodial_offline_actor_contexts','native_scan_entry_id'),('public.custodial_offline_actor_contexts','native_start_attestation_version'),('public.custodial_offline_actor_contexts','occurrence_fingerprint'),('public.custodial_offline_actor_contexts','occurrence_id'),('public.custodial_offline_actor_contexts','started_at'),('public.custodial_offline_actor_contexts','status'),('public.sessions','client_session_id'),('public.sessions','device_id'),('public.sessions','employee_id'),('public.sessions','ended_at'),('public.sessions','id'),('public.sessions','location_id'),('public.sessions','started_at'),('public.sessions','status'),('public.completion_responses','client_completion_id'),('public.completion_responses','device_id'),('public.completion_responses','id'),('public.completion_responses','location_id'),('public.completion_responses','response_json'),('public.completion_responses','session_id'),('public.completion_responses','submitted_by_employee_id'),('public.custodial_offline_scan_event_evidence','client_event_id'),('public.custodial_offline_scan_event_evidence','context_id'),('public.custodial_offline_scan_event_evidence','event_payload'),('public.custodial_offline_scan_event_evidence','reconciliation_id'),('public.custodial_offline_scan_event_evidence','session_id')), native_columns as (
 select e.*,a.attnum is not null present,format_type(a.atttypid,a.atttypmod) sql_type
 from required_native_columns e left join pg_attribute a on a.attrelid=to_regclass(e.relation_name)
 and a.attname=e.column_name and a.attnum>0 and not a.attisdropped
), required_view_columns(column_name) as (values
('location_id'),('location_code'),('location_name'),('location_type'),('form_type'),('latest_employee_name'),('latest_completed_at'),('latest_checked_at'),('latest_completed_session_id'),('latest_completed_session_uuid'),('latest_completed_at_display'),('services_performed'),('open_ticket_count'),('status_code'),('status_color'),('duration_display'),('open_session_status'),('open_session_uuid'),('open_session_device_identifier'),('open_session_employee_name'),('open_session_started_at_display')), view_columns as (
 select e.column_name,a.attnum is not null present,format_type(a.atttypid,a.atttypmod) sql_type,
 case when a.attnum is null then false else has_column_privilege('custodial_application_reader',a.attrelid,a.attnum,'SELECT') end reader_select
 from required_view_columns e left join pg_attribute a on a.attrelid=to_regclass('public.v_location_dashboard_status')
 and a.attname=e.column_name and a.attnum>0 and not a.attisdropped
)
select jsonb_build_object('scope','custodial-dashboard-candidate-prerequisites-only',
 'helpers',(select jsonb_agg(to_jsonb(h) order by signature) from helpers h),
 'native_missing_columns',(select coalesce(jsonb_agg(to_jsonb(c) order by relation_name,column_name),'[]'::jsonb) from native_columns c where not present),
 'native_columns',(select jsonb_agg(to_jsonb(c) order by relation_name,column_name) from native_columns c),
 'view_columns',(select jsonb_agg(to_jsonb(c) order by column_name) from view_columns c),
 'view',(select jsonb_build_object('owner',r.rolname,'options',v.reloptions,'definition_md5',md5(pg_get_viewdef(v.oid,true)),
  'definition_sql',pg_get_viewdef(v.oid,true)) from pg_class v join pg_roles r on r.oid=v.relowner where v.oid=to_regclass('public.v_location_dashboard_status')));
